# frozen_string_literal: true

module Spree
  module Pos
    # One asynchronous report export. The CSV is generated by
    # GenerateExportJob under the requester's scope, stored as an Active
    # Storage attachment, downloadable only by the requester while they still
    # hold the export capability, and purged after the TTL.
    class ExportRequest < Record
      self.table_name = 'spree_pos_export_requests'
      has_prefix_id :posexport

      TTL = 24.hours
      STATUSES = %w[queued processing ready failed expired].freeze

      belongs_to :store, class_name: 'Spree::Store'
      belongs_to :branch, class_name: 'Spree::Pos::Branch'
      belongs_to :requester, class_name: staff_class_name
      has_one_attached :file

      validates :report_type, inclusion: { in: Reports::TYPES }
      validates :status, inclusion: { in: STATUSES }
      validates :expires_at, presence: true

      scope :for_store, ->(store) { where(store_id: store.id) }
      scope :expired_now, -> { where(expires_at: ..Time.current).where.not(status: 'expired') }

      def expired?
        status == 'expired' || expires_at <= Time.current
      end

      def to_pos
        {
          id: prefixed_id, branch_id: branch.prefixed_id, report_type: report_type, filters: filters,
          status: expired? ? 'expired' : status, row_count: row_count, error_message: error_message,
          expires_at: expires_at.iso8601, completed_at: completed_at&.iso8601, created_at: created_at&.iso8601
        }
      end
    end
  end
end
